"""CLI interface for jina-grep."""

import sys
from pathlib import Path

import click

from .client import SearchOptions, pipe_rerank, semantic_grep, semantic_classify
from .server import server_status, start_server, stop_server


@click.group()
def serve():
    """Manage the embedding server."""
    pass


@serve.command()
@click.option("--host", default="127.0.0.1", help="Host to bind to")
@click.option("--port", type=int, default=8089, help="Port to bind to")
@click.option("--foreground", is_flag=True, help="Run in foreground")
def start(host, port, foreground):
    """Start the embedding server."""
    start_server(host=host, port=port, daemon=not foreground)


@serve.command()
def stop():
    """Stop the embedding server."""
    stop_server()


@serve.command()
def status():
    """Check embedding server status."""
    server_status()


def main():
    """Entry point: routes to 'serve' subcommand or grep mode."""
    args = sys.argv[1:]

    if args and args[0] == "serve":
        serve(args[1:], standalone_mode=True)
        return

    grep_main(args)


def grep_main(args=None):
    """Grep CLI."""

    @click.command()
    @click.option("-r", "-R", "--recursive", is_flag=True, help="Recursive search")
    @click.option("-l", "--files-with-matches", is_flag=True, help="Print only filenames with matches")
    @click.option("-L", "--files-without-match", is_flag=True, help="Print only filenames without matches")
    @click.option("-c", "--count", is_flag=True, help="Print match count per file")
    @click.option("-n", "--line-number", is_flag=True, default=True, help="Print line numbers")
    @click.option("-H", "--with-filename", is_flag=True, default=None, help="Print filename with matches")
    @click.option("--no-filename", is_flag=True, help="Suppress filename")
    @click.option("-A", "--after-context", type=int, default=0, help="Lines after match")
    @click.option("-B", "--before-context", type=int, default=0, help="Lines before match")
    @click.option("-C", "--context", type=int, default=0, help="Lines before and after match")
    @click.option("--include", multiple=True, help="Search only files matching GLOB")
    @click.option("--exclude", multiple=True, help="Skip files matching GLOB")
    @click.option("--exclude-dir", multiple=True, help="Skip directories matching GLOB")
    @click.option("--color", type=click.Choice(["never", "always", "auto"]), default="auto")
    @click.option("-v", "--invert-match", is_flag=True, help="Invert match (lowest similarity)")
    @click.option("-m", "--max-count", type=int, help="Max matches per file")
    @click.option("-q", "--quiet", is_flag=True, help="Quiet mode")
    @click.option("-o", "--only-matching", is_flag=True, help="Print only matching label (classification mode)")
    @click.option("-e", "--regexp", multiple=True, help="Classification labels (multiple -e for zero-shot classification)")
    @click.option("-f", "--file", "label_file", type=click.Path(exists=True), help="Read classification labels from file (one per line)")
    @click.option("--threshold", type=float, default=None, help="Similarity threshold (default: 0.5, ignored when --top-k is set)")
    @click.option("--top-k", type=int, default=None, help="Max results")
    @click.option("--model", default="jina-embeddings-v5-nano", help="Model name")
    @click.option("--task", type=click.Choice(["retrieval", "text-matching", "clustering", "classification", "nl2code", "qa", "code2code", "code2nl", "code2completion"]), default=None, help="Embedding task (auto-detected)")
    @click.option("--server", default="http://localhost:8089", help="Server URL")
    @click.option("--granularity", type=click.Choice(["line", "paragraph", "sentence", "token"]), default="token")
    @click.argument("pattern", required=False, default=None)
    @click.argument("files", nargs=-1, type=click.Path())
    def _grep(
        recursive, files_with_matches, files_without_match, count, line_number,
        with_filename, no_filename, after_context, before_context, context,
        include, exclude, exclude_dir, color, invert_match, max_count, quiet,
        only_matching, regexp, label_file, threshold, top_k, model, task,
        server, granularity, pattern, files,
    ):
        """Semantic grep using Jina embeddings.

        PATTERN is a natural language query (not regex).

        \b
        Pipe mode (rerank grep output):
            grep -rn "error" src/ | jina-grep "error handling"

        \b
        Standalone mode (direct semantic search):
            jina-grep "error handling" src/
            jina-grep -r --threshold=0.6 "database connection" .

        \b
        Zero-shot classification:
            jina-grep -e "bug" -e "feature" -e "docs" src/
            jina-grep -f labels.txt src/

        \b
        Server:
            jina-grep serve start    Start embedding server
            jina-grep serve stop     Stop embedding server
            jina-grep serve status   Check server status
        """
        # Collect labels from -e and -f
        labels = list(regexp)
        if label_file:
            with open(label_file) as lf:
                labels.extend(line.strip() for line in lf if line.strip())

        # Classification mode: multiple labels provided
        if labels:
            if not files and pattern:
                # pattern is actually a file path
                files = (pattern,) + files if pattern else files
                if pattern:
                    files = (pattern,)
            elif not files:
                files = (".",)

            use_color = color == "always" or (color == "auto" and sys.stdout.isatty())
            show_fn = not no_filename and (with_filename or len(files) > 1 or recursive)

            _threshold = threshold if threshold is not None else 0.5
            _top_k = top_k if top_k is not None else 10

            classify_options = SearchOptions(
                recursive=recursive,
                files_with_matches=files_with_matches,
                files_without_match=files_without_match,
                count=count,
                line_number=line_number,
                with_filename=show_fn,
                after_context=after_context if context == 0 else context,
                before_context=before_context if context == 0 else context,
                include_patterns=list(include),
                exclude_patterns=list(exclude),
                exclude_dir_patterns=list(exclude_dir),
                color=use_color,
                invert_match=invert_match,
                max_count=max_count,
                quiet=quiet,
                threshold=_threshold,
                top_k=_top_k,
                model=model,
                task="classification",
                server_url=server,
                granularity=granularity,
            )

            paths = []
            for f in files:
                p = Path(f)
                if not p.exists():
                    print(f"jina-grep: {f}: No such file or directory", file=sys.stderr)
                    continue
                paths.append(p)

            if not paths:
                sys.exit(2)

            exit_code = semantic_classify(labels, paths, classify_options, only_matching=only_matching)
            sys.exit(exit_code)

        # Standard grep mode requires a pattern
        if not pattern:
            print("Error: PATTERN is required (or use -e for classification)", file=sys.stderr)
            sys.exit(2)

        if no_filename:
            show_filename = False
        elif with_filename is not None:
            show_filename = with_filename
        else:
            show_filename = len(files) > 1 or recursive

        if context > 0:
            after_context = context
            before_context = context

        use_color = color == "always" or (color == "auto" and sys.stdout.isatty())

        # When --top-k is set without --threshold, disable threshold filtering
        if top_k is not None and threshold is None:
            threshold = 0.0
        if threshold is None:
            threshold = 0.5
        if top_k is None:
            top_k = 10

        options = SearchOptions(
            recursive=recursive,
            files_with_matches=files_with_matches,
            files_without_match=files_without_match,
            count=count,
            line_number=line_number,
            with_filename=show_filename,
            after_context=after_context,
            before_context=before_context,
            include_patterns=list(include),
            exclude_patterns=list(exclude),
            exclude_dir_patterns=list(exclude_dir),
            color=use_color,
            invert_match=invert_match,
            max_count=max_count,
            quiet=quiet,
            threshold=threshold,
            top_k=top_k,
            model=model,
            task=task or "retrieval",
            server_url=server,
            granularity=granularity,
        )

        # Pipe mode: stdin has data and is not a TTY
        # Also check if files were provided -- if so, prefer standalone mode
        if not sys.stdin.isatty() and not files:
            import select
            if select.select([sys.stdin], [], [], 0.0)[0]:
                exit_code = pipe_rerank(pattern, options)
                sys.exit(exit_code)

        # Standalone mode: need files
        if not files:
            files = (".",)

        paths = []
        for f in files:
            p = Path(f)
            if not p.exists():
                print(f"jina-grep: {f}: No such file or directory", file=sys.stderr)
                continue
            paths.append(p)

        if not paths:
            sys.exit(2)

        exit_code = semantic_grep(pattern, paths, options)
        sys.exit(exit_code)

    _grep(args, standalone_mode=True)


if __name__ == "__main__":
    main()

"""FastAPI server for local embedding generation using pure MLX."""

import os
import signal
import sys
from pathlib import Path
from typing import Optional

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

from .embedder import (
    MLX_MODELS,
    CODE_MODELS,
    CODE_MODELS_MAP,
    MATRYOSHKA_DIMS,
    VALID_TASKS,
    CODE_TASKS,
    ALL_TASKS,
    VALID_PROMPT_NAMES,
    MAX_BATCH_SIZE,
    MAX_SEQ_LENGTH,
    get_model,
)

app = FastAPI(title="Jina Grep Embedding Server")


class EmbeddingRequest(BaseModel):
    input: list[str]
    model: str = "jina-embeddings-v5-nano"
    task: str = "retrieval"
    prompt_name: Optional[str] = "query"
    truncate_dim: Optional[int] = None


class EmbeddingData(BaseModel):
    object: str = "embedding"
    index: int
    embedding: list[float]


class UsageInfo(BaseModel):
    prompt_tokens: int
    total_tokens: int


class EmbeddingResponse(BaseModel):
    object: str = "list"
    data: list[EmbeddingData]
    model: str
    usage: UsageInfo


def count_tokens(texts: list[str]) -> int:
    """Approximate token count."""
    return int(sum(len(t.split()) for t in texts) * 1.3)


@app.post("/v1/embeddings", response_model=EmbeddingResponse)
async def create_embeddings(request: EmbeddingRequest):
    """Generate embeddings for input texts."""
    if not request.input:
        raise HTTPException(status_code=400, detail="Input cannot be empty")

    if len(request.input) > MAX_BATCH_SIZE:
        raise HTTPException(
            status_code=400,
            detail=f"Batch size {len(request.input)} exceeds maximum {MAX_BATCH_SIZE}",
        )

    task = request.task
    is_code = request.model in CODE_MODELS
    valid = CODE_TASKS if is_code else VALID_TASKS
    if task not in valid:
        raise HTTPException(status_code=400, detail=f"Invalid task: {task}. Must be one of: {', '.join(sorted(valid))}")

    if request.truncate_dim is not None and request.truncate_dim not in MATRYOSHKA_DIMS:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid truncate_dim: {request.truncate_dim}. Must be one of: {sorted(MATRYOSHKA_DIMS)}",
        )

    try:
        cached = get_model(request.model, task)
    except (ValueError, RuntimeError) as e:
        raise HTTPException(status_code=400, detail=str(e))

    try:
        import mlx.core as mx

        if is_code:
            # Code models: (model, tokenizer) tuple
            model, tokenizer = cached
            prompt_type = request.prompt_name or "query"
            if prompt_type == "document":
                prompt_type = "passage"
            embeddings = model.encode(
                request.input,
                tokenizer,
                task=task,
                prompt_type=prompt_type,
                truncate_dim=request.truncate_dim,
            )
        else:
            # v5 models: JinaMultiTaskModel with dynamic LoRA
            multi_model = cached
            multi_model.switch_task(task)

            if task == "retrieval":
                prompt_name = request.prompt_name or "query"
                if prompt_name not in VALID_PROMPT_NAMES:
                    raise HTTPException(status_code=400, detail=f"Invalid prompt_name: {prompt_name}")
                task_type = f"retrieval.{prompt_name}" if prompt_name == "query" else "retrieval.passage"
            else:
                task_type = task
            embeddings = multi_model.encode(
                request.input,
                task_type=task_type,
            )
        mx.eval(embeddings)
        embeddings = embeddings.tolist()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Encoding failed: {e}")

    data = [
        EmbeddingData(index=i, embedding=emb)
        for i, emb in enumerate(embeddings)
    ]

    token_count = count_tokens(request.input)

    return EmbeddingResponse(
        data=data,
        model=request.model,
        usage=UsageInfo(prompt_tokens=token_count, total_tokens=token_count),
    )


@app.get("/health")
async def health():
    return {"status": "ok"}


@app.get("/models")
async def list_models():
    return {
        "models": {
            **{name: list(VALID_TASKS) for name in MLX_MODELS},
            **{name: list(CODE_TASKS) for name in CODE_MODELS_MAP},
        },
        "matryoshka_dims": sorted(MATRYOSHKA_DIMS),
        "max_seq_length": MAX_SEQ_LENGTH,
    }


# --- PID management ---

def get_pid_file() -> Path:
    pid_dir = Path.home() / ".jina-grep"
    pid_dir.mkdir(exist_ok=True)
    return pid_dir / "server.pid"


def write_pid():
    get_pid_file().write_text(str(os.getpid()))


def read_pid() -> Optional[int]:
    pid_file = get_pid_file()
    if pid_file.exists():
        try:
            return int(pid_file.read_text().strip())
        except (ValueError, OSError):
            return None
    return None


def remove_pid():
    pid_file = get_pid_file()
    if pid_file.exists():
        pid_file.unlink()


def is_server_running() -> tuple[bool, Optional[int]]:
    pid = read_pid()
    if pid is None:
        return False, None
    try:
        os.kill(pid, 0)
        return True, pid
    except OSError:
        remove_pid()
        return False, None


def start_server(host: str = "127.0.0.1", port: int = 8089, daemon: bool = True):
    running, pid = is_server_running()
    if running:
        print(f"Server already running (PID: {pid})")
        return

    if daemon:
        import subprocess
        log_dir = Path.home() / ".jina-grep"
        log_dir.mkdir(exist_ok=True)
        log_file = log_dir / "server.log"

        with open(log_file, "a") as lf:
            proc = subprocess.Popen(
                [sys.executable, "-m", "jina_grep.server", "--host", host, "--port", str(port)],
                stdout=lf,
                stderr=lf,
                start_new_session=True,
            )
        print(f"Server starting in background (PID: {proc.pid})")
        return

    import uvicorn
    write_pid()

    def cleanup(signum, frame):
        remove_pid()
        sys.exit(0)

    signal.signal(signal.SIGTERM, cleanup)
    signal.signal(signal.SIGINT, cleanup)

    try:
        uvicorn.run(app, host=host, port=port, log_level="info")
    finally:
        remove_pid()


def stop_server():
    running, pid = is_server_running()
    if not running:
        print("Server is not running")
        return
    try:
        os.kill(pid, signal.SIGTERM)
        print(f"Server stopped (PID: {pid})")
        remove_pid()
    except OSError as e:
        print(f"Failed to stop server: {e}")
        remove_pid()


def server_status():
    running, pid = is_server_running()
    if running:
        print(f"Server is running (PID: {pid})")
    else:
        print("Server is not running")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8089)
    args = parser.parse_args()

    import uvicorn
    write_pid()

    def cleanup(signum, frame):
        remove_pid()
        sys.exit(0)

    signal.signal(signal.SIGTERM, cleanup)
    signal.signal(signal.SIGINT, cleanup)

    try:
        uvicorn.run(app, host=args.host, port=args.port, log_level="info")
    finally:
        remove_pid()

"""Client for embedding server and semantic search logic."""

import fnmatch
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterator, Optional

import httpx
import numpy as np

from .embedder import LocalEmbedder


def _get_client(server_url: str = "http://localhost:8089"):
    """Get embedding client: use HTTP if persistent server is running, else local MLX."""
    try:
        client = EmbeddingClient(server_url)
        if client.health_check():
            return client
        client.close()
    except Exception:
        pass
    return LocalEmbedder()


@dataclass
class SearchResult:
    """A single search result."""
    filepath: str
    line_number: int
    line: str
    score: float
    context_before: list[str] = field(default_factory=list)
    context_after: list[str] = field(default_factory=list)
    original_prefix: str = ""  # preserve original grep prefix for pipe mode


@dataclass
class SearchOptions:
    """Search configuration options."""
    recursive: bool = False
    files_with_matches: bool = False
    files_without_match: bool = False
    count: bool = False
    line_number: bool = True
    with_filename: bool = True
    after_context: int = 0
    before_context: int = 0
    include_patterns: list[str] = None
    exclude_patterns: list[str] = None
    exclude_dir_patterns: list[str] = None
    color: bool = True
    invert_match: bool = False
    max_count: Optional[int] = None
    quiet: bool = False
    threshold: float = 0.5
    top_k: int = 10
    model: str = "jina-embeddings-v5-nano"
    task: str = "retrieval"
    server_url: str = "http://localhost:8089"
    granularity: str = "token"

    def __post_init__(self):
        if self.include_patterns is None:
            self.include_patterns = []
        if self.exclude_patterns is None:
            self.exclude_patterns = []
        if self.exclude_dir_patterns is None:
            self.exclude_dir_patterns = []


class EmbeddingClient:
    """Client for the local embedding server."""

    def __init__(self, server_url: str = "http://localhost:8089"):
        self.server_url = server_url.rstrip("/")
        # Bypass system proxy for localhost connections
        self.client = httpx.Client(timeout=120.0, proxy=None)

    def embed(
        self,
        texts: list[str],
        model: str = "jina-embeddings-v5-nano",
        task: str = "retrieval",
        prompt_name: str = None,
        batch_size: int = 256,
    ) -> np.ndarray:
        """Get embeddings for texts. Auto-batches large inputs."""
        if len(texts) <= batch_size:
            return self._embed_batch(texts, model, task, prompt_name)

        # Batch large inputs to avoid HTTP payload issues
        all_embeddings = []
        for i in range(0, len(texts), batch_size):
            batch = texts[i : i + batch_size]
            embs = self._embed_batch(batch, model, task, prompt_name)
            all_embeddings.append(embs)
        return np.vstack(all_embeddings)

    def _embed_batch(
        self,
        texts: list[str],
        model: str,
        task: str,
        prompt_name: str = None,
    ) -> np.ndarray:
        """Embed a single batch."""
        payload = {"input": texts, "model": model, "task": task}
        if prompt_name:
            payload["prompt_name"] = prompt_name
        response = self.client.post(
            f"{self.server_url}/v1/embeddings",
            json=payload,
        )
        response.raise_for_status()
        data = response.json()
        embeddings = [d["embedding"] for d in data["data"]]
        return np.array(embeddings)

    def health_check(self) -> bool:
        """Check if server is healthy."""
        try:
            response = self.client.get(f"{self.server_url}/health")
            return response.status_code == 200
        except Exception:
            return False

    def close(self):
        """Close the client."""
        self.client.close()


def cosine_similarity(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    """Compute cosine similarity between vectors."""
    a_norm = a / (np.linalg.norm(a, axis=-1, keepdims=True) + 1e-9)
    b_norm = b / (np.linalg.norm(b, axis=-1, keepdims=True) + 1e-9)

    if a_norm.ndim == 1:
        a_norm = a_norm.reshape(1, -1)

    return np.dot(a_norm, b_norm.T).flatten()


# ---------------------------------------------------------------------------
# Pipe mode: parse grep output, rerank semantically
# ---------------------------------------------------------------------------

# Match grep output: filename:linenum:content or filename:content or just content
GREP_LINE_RE = re.compile(
    r"^(?:(?P<file>[^:]+):)?(?:(?P<lineno>\d+):)?(?P<content>.*)$"
)

# Strip ANSI escape sequences for embedding
ANSI_RE = re.compile(r"\x1b\[[0-9;]*m")


def parse_grep_line(line: str) -> tuple[str, int, str, str]:
    """Parse a grep output line. Returns (filepath, lineno, content, raw_line)."""
    m = GREP_LINE_RE.match(line)
    if not m:
        return ("", 0, line, line)

    filepath = m.group("file") or ""
    lineno = int(m.group("lineno")) if m.group("lineno") else 0
    content = m.group("content") or ""
    return (filepath, lineno, content, line)


def pipe_rerank(
    pattern: str,
    options: SearchOptions,
) -> int:
    """Read grep output from stdin, rerank by semantic similarity."""
    client = _get_client(options.server_url)

    # Read all stdin lines
    raw_lines = []
    for line in sys.stdin:
        line = line.rstrip("\n")
        if line:
            raw_lines.append(line)

    if not raw_lines:
        return 1

    # Parse grep output
    parsed = [parse_grep_line(l) for l in raw_lines]
    contents = [ANSI_RE.sub("", p[2]) for p in parsed]

    # Filter out empty content
    valid = [(i, c) for i, c in enumerate(contents) if c.strip()]
    if not valid:
        return 1

    valid_indices = [v[0] for v in valid]
    valid_contents = [v[1] for v in valid]

    # Embed query
    try:
        query_kwargs = {"task": options.task}
        if options.task in ("retrieval", "nl2code", "qa", "code2code", "code2nl", "code2completion"):
            query_kwargs["prompt_name"] = "query"
        query_emb = client.embed([pattern], model=options.model, **query_kwargs)[0]
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return 2

    # Embed contents (batch)
    try:
        doc_kwargs = {"task": options.task}
        if options.task in ("retrieval", "nl2code", "qa", "code2code", "code2nl", "code2completion"):
            doc_kwargs["prompt_name"] = "document"
        content_embs = client.embed(valid_contents, model=options.model, **doc_kwargs)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return 2

    client.close()

    # Compute similarity
    scores = cosine_similarity(query_emb, content_embs)

    # Build scored results
    scored = list(zip(valid_indices, scores))

    if options.invert_match:
        scored.sort(key=lambda x: x[1])
    else:
        scored.sort(key=lambda x: -x[1])

    # Apply threshold and top_k
    results = []
    for idx, score in scored:
        if not options.invert_match and score < options.threshold:
            continue
        if options.invert_match and score >= options.threshold:
            continue
        results.append((idx, score))
        if len(results) >= options.top_k:
            break

    if options.quiet:
        return 0 if results else 1

    # Output: original grep line + score annotation
    for idx, score in results:
        raw_line = raw_lines[idx]
        if options.color:
            # Append score in dim text
            print(f"{raw_line}  \033[2m[{score:.3f}]\033[0m")
        else:
            print(f"{raw_line}  [{score:.3f}]")

    return 0 if results else 1


# ---------------------------------------------------------------------------
# Standalone mode: read files directly, semantic search
# ---------------------------------------------------------------------------

def _estimate_tokens(text: str) -> int:
    """Rough token estimate: ~4 chars per token for English, ~2 for CJK."""
    return max(1, len(text) // 3)


def split_into_chunks(
    content: str,
    granularity: str = "token",
    chunk_tokens: int = 512,
) -> list[tuple[int, str]]:
    """Split content into chunks with line numbers (1-indexed).

    Granularity modes:
    - line: one chunk per non-empty line
    - paragraph: split on blank lines
    - sentence: split on sentence-ending punctuation
    - token: fixed token window (default 512 tokens), split at line boundaries
    """
    lines = content.splitlines()

    if granularity == "line":
        return [(i + 1, line) for i, line in enumerate(lines) if line.strip()]

    elif granularity == "paragraph":
        chunks = []
        current_chunk = []
        start_line = 1

        for i, line in enumerate(lines):
            if line.strip():
                if not current_chunk:
                    start_line = i + 1
                current_chunk.append(line)
            elif current_chunk:
                chunks.append((start_line, "\n".join(current_chunk)))
                current_chunk = []

        if current_chunk:
            chunks.append((start_line, "\n".join(current_chunk)))

        return chunks

    elif granularity == "sentence":
        chunks = []
        for i, line in enumerate(lines):
            if not line.strip():
                continue
            sentences = re.split(r"(?<=[.!?。！？])\s*", line)
            for sentence in sentences:
                if sentence.strip():
                    chunks.append((i + 1, sentence.strip()))
        return chunks

    elif granularity == "token":
        chunks = []
        current_chunk = []
        current_tokens = 0
        start_line = 1

        for i, line in enumerate(lines):
            if not line.strip():
                continue
            line_tokens = _estimate_tokens(line)
            if current_chunk and current_tokens + line_tokens > chunk_tokens:
                chunks.append((start_line, "\n".join(current_chunk)))
                current_chunk = []
                current_tokens = 0
            if not current_chunk:
                start_line = i + 1
            current_chunk.append(line)
            current_tokens += line_tokens

        if current_chunk:
            chunks.append((start_line, "\n".join(current_chunk)))

        return chunks

    else:
        return [(i + 1, line) for i, line in enumerate(lines) if line.strip()]


def should_include_file(filepath: Path, options: SearchOptions) -> bool:
    """Check if file should be included based on patterns."""
    filename = filepath.name

    if options.include_patterns:
        if not any(fnmatch.fnmatch(filename, p) for p in options.include_patterns):
            return False

    if options.exclude_patterns:
        if any(fnmatch.fnmatch(filename, p) for p in options.exclude_patterns):
            return False

    return True


def should_exclude_dir(dirpath: Path, options: SearchOptions) -> bool:
    """Check if directory should be excluded."""
    dirname = dirpath.name

    default_excludes = {".git", ".svn", ".hg", "__pycache__", "node_modules", ".venv", "venv"}
    if dirname in default_excludes:
        return True

    if options.exclude_dir_patterns:
        if any(fnmatch.fnmatch(dirname, p) for p in options.exclude_dir_patterns):
            return True

    return False


def get_files(paths: list[Path], options: SearchOptions) -> Iterator[Path]:
    """Get files to search."""
    for path in paths:
        if path.is_file():
            if should_include_file(path, options):
                yield path
        elif path.is_dir():
            if options.recursive:
                for item in sorted(path.iterdir()):
                    if item.is_dir():
                        if not should_exclude_dir(item, options):
                            yield from get_files([item], options)
                    elif item.is_file():
                        if should_include_file(item, options):
                            yield item
            else:
                for item in sorted(path.iterdir()):
                    if item.is_file() and should_include_file(item, options):
                        yield item


def read_file_safely(filepath: Path) -> Optional[str]:
    """Read file content, handling encoding errors."""
    try:
        return filepath.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        try:
            return filepath.read_text(encoding="latin-1")
        except Exception:
            return None
    except Exception:
        return None


def search_file(
    filepath: Path,
    query_embedding: np.ndarray,
    client: EmbeddingClient,
    options: SearchOptions,
) -> list[SearchResult]:
    """Search a single file for semantic matches."""
    content = read_file_safely(filepath)
    if content is None:
        return []

    chunks = split_into_chunks(content, options.granularity)
    if not chunks:
        return []

    chunk_texts = [c[1] for c in chunks]

    try:
        doc_kwargs = {"task": options.task}
        if options.task in ("retrieval", "nl2code", "qa", "code2code", "code2nl", "code2completion"):
            doc_kwargs["prompt_name"] = "document"
        chunk_embeddings = client.embed(
            chunk_texts,
            model=options.model,
            **doc_kwargs,
        )
    except Exception:
        return []

    similarities = cosine_similarity(query_embedding, chunk_embeddings)

    results = []
    lines = content.splitlines()

    for idx, (line_num, chunk_text) in enumerate(chunks):
        score = float(similarities[idx])

        if options.invert_match:
            if score >= options.threshold:
                continue
        else:
            if score < options.threshold:
                continue

        context_before = []
        context_after = []

        if options.before_context > 0:
            start = max(0, line_num - 1 - options.before_context)
            context_before = lines[start : line_num - 1]

        if options.after_context > 0:
            end = min(len(lines), line_num + options.after_context)
            context_after = lines[line_num : end]

        results.append(
            SearchResult(
                filepath=str(filepath),
                line_number=line_num,
                line=chunk_text,
                score=score,
                context_before=context_before,
                context_after=context_after,
            )
        )

    if options.invert_match:
        results.sort(key=lambda r: r.score)
    else:
        results.sort(key=lambda r: -r.score)

    if options.max_count is not None:
        results = results[: options.max_count]

    return results


def format_result(result: SearchResult, options: SearchOptions) -> str:
    """Format a search result for output."""
    parts = []

    if options.with_filename:
        if options.color:
            parts.append(f"\033[35m{result.filepath}\033[0m")
        else:
            parts.append(result.filepath)

    if options.line_number:
        if options.color:
            parts.append(f"\033[32m{result.line_number}\033[0m")
        else:
            parts.append(str(result.line_number))

    if parts:
        prefix = ":".join(parts) + ":"
    else:
        prefix = ""

    line = result.line
    if options.color:
        line = f"\033[1m{line}\033[0m"

    # Score annotation
    if options.color:
        score_str = f"  \033[2m[{result.score:.3f}]\033[0m"
    else:
        score_str = f"  [{result.score:.3f}]"

    output_lines = []

    for ctx_line in result.context_before:
        ctx_prefix = prefix.replace(":", "-") if prefix else ""
        output_lines.append(f"{ctx_prefix}{ctx_line}")

    output_lines.append(f"{prefix}{line}{score_str}")

    for ctx_line in result.context_after:
        ctx_prefix = prefix.replace(":", "-") if prefix else ""
        output_lines.append(f"{ctx_prefix}{ctx_line}")

    return "\n".join(output_lines)


def semantic_classify(
    labels: list[str],
    paths: list[Path],
    options: SearchOptions,
    only_matching: bool = False,
) -> int:
    """Zero-shot classification: assign best label to each line/chunk."""
    client = _get_client(options.server_url)

    # Embed all labels
    try:
        label_embs = client.embed(labels, model=options.model, task="classification")
    except Exception as e:
        if not options.quiet:
            print(f"Error embedding labels: {e}", file=sys.stderr)
        return 2

    files = list(get_files(paths, options))
    if not files:
        if not options.quiet:
            print("No files to search", file=sys.stderr)
        return 1

    has_output = False

    if options.count:
        # Count mode: tally per label
        label_counts = {label: 0 for label in labels}

    for filepath in files:
        content = read_file_safely(filepath)
        if content is None:
            continue

        chunks = split_into_chunks(content, options.granularity)
        if not chunks:
            continue

        chunk_texts = [c[1] for c in chunks]

        try:
            chunk_embs = client.embed(chunk_texts, model=options.model, task="classification")
        except Exception:
            continue

        # Compute similarity: each chunk against all labels
        # chunk_embs: [N, D], label_embs: [L, D]
        chunk_norm = chunk_embs / (np.linalg.norm(chunk_embs, axis=-1, keepdims=True) + 1e-9)
        label_norm = label_embs / (np.linalg.norm(label_embs, axis=-1, keepdims=True) + 1e-9)
        scores_matrix = np.dot(chunk_norm, label_norm.T)  # [N, L]

        for idx, (line_num, chunk_text) in enumerate(chunks):
            best_label_idx = int(np.argmax(scores_matrix[idx]))
            best_score = float(scores_matrix[idx, best_label_idx])
            best_label = labels[best_label_idx]

            if best_score < options.threshold:
                continue

            has_output = True

            if options.quiet:
                continue

            if options.count:
                label_counts[best_label] += 1
                continue

            if only_matching:
                print(best_label)
                continue

            # Format output: filepath:linenum:content [label:score]
            parts = []
            if options.with_filename:
                if options.color:
                    parts.append(f"\033[35m{filepath}\033[0m")
                else:
                    parts.append(str(filepath))
            if options.line_number:
                if options.color:
                    parts.append(f"\033[32m{line_num}\033[0m")
                else:
                    parts.append(str(line_num))

            prefix = ":".join(parts) + ":" if parts else ""
            line_display = f"\033[1m{chunk_text}\033[0m" if options.color else chunk_text

            # Show all label scores
            all_scores = []
            for li, label in enumerate(labels):
                s = float(scores_matrix[idx, li])
                if li == best_label_idx:
                    if options.color:
                        all_scores.append(f"\033[1;33m{label}:{s:.3f}\033[0m")
                    else:
                        all_scores.append(f"{label}:{s:.3f}")
                else:
                    if options.color:
                        all_scores.append(f"\033[2m{label}:{s:.3f}\033[0m")
                    else:
                        all_scores.append(f"{label}:{s:.3f}")

            score_str = "  [" + " ".join(all_scores) + "]"
            print(f"{prefix}{line_display}{score_str}")

    client.close()

    if options.quiet:
        return 0 if has_output else 1

    if options.count:
        for label, cnt in sorted(label_counts.items(), key=lambda x: -x[1]):
            print(f"{label}: {cnt}")
        return 0 if has_output else 1

    return 0 if has_output else 1


def semantic_grep(
    pattern: str,
    paths: list[Path],
    options: SearchOptions,
) -> int:
    """Main semantic grep function. Returns exit code."""
    client = _get_client(options.server_url)

    try:
        query_kwargs = {"task": options.task}
        if options.task in ("retrieval", "nl2code", "qa", "code2code", "code2nl", "code2completion"):
            query_kwargs["prompt_name"] = "query"
        query_embedding = client.embed([pattern], model=options.model, **query_kwargs)[0]
    except Exception as e:
        if not options.quiet:
            print(f"Error getting query embedding: {e}", file=sys.stderr)
        return 2

    files = list(get_files(paths, options))
    if not files:
        if not options.quiet:
            print("No files to search", file=sys.stderr)
        return 1

    file_results: dict[str, list[SearchResult]] = {}
    all_results: list[SearchResult] = []

    for filepath in files:
        results = search_file(filepath, query_embedding, client, options)
        if results:
            file_results[str(filepath)] = results
            all_results.extend(results)

    client.close()

    if options.quiet:
        return 0 if all_results else 1

    if options.files_with_matches:
        for filepath in file_results:
            print(filepath)
        return 0 if file_results else 1

    if options.files_without_match:
        matched_files = set(file_results.keys())
        for filepath in files:
            if str(filepath) not in matched_files:
                print(filepath)
        return 0

    if options.count:
        for filepath, results in file_results.items():
            if options.with_filename:
                print(f"{filepath}:{len(results)}")
            else:
                print(len(results))
        return 0 if file_results else 1

    # Sort all results by score and take top_k
    if options.invert_match:
        all_results.sort(key=lambda r: r.score)
    else:
        all_results.sort(key=lambda r: -r.score)

    all_results = all_results[: options.top_k]

    for result in all_results:
        print(format_result(result, options))

    return 0 if all_results else 1
